const DOCS_DB = 'f1ae9f21-8aa0-4327-bde5-3c4aa7f13f2b';
const REGISTER_DB = '7258a074-49a6-444f-adc1-86a61cc3a77e';
let V = {};
try { const v = $vars || {}; V = { db: v.BP3_UPLOADED_DOCS_DB }; } catch (e) { V = {}; }
const dbId = V.db || DOCS_DB;
const meta = $('مدخلات الملف').first().json || {};
let qrTxt = '';
try { qrTxt = ($('تجهيز طلب AI').first().json || {}).qrData || ''; } catch (e) { qrTxt = ''; }
const r = $input.first().json || {};
let txt = '';
if (r.choices && r.choices[0] && r.choices[0].message) txt = r.choices[0].message.content || '';
if (!txt) txt = r.content || r.text || r.response || r.output || r.data || '';
if (Array.isArray(txt)) txt = txt.map(x => (x && (x.text || x.content)) || '').join(' ');
if (typeof txt !== 'string') txt = JSON.stringify(txt);
let fields = {};
try { const m = txt.match(/\{[\s\S]*\}/); if (m) fields = JSON.parse(m[0]); } catch (e) { fields = {}; }
if (fields && fields.identifiers && typeof fields.identifiers === 'object') {
  try { fields.identifiers = Object.entries(fields.identifiers).map(function (kv) { return kv[0] + ': ' + kv[1]; }).join(' · '); } catch (e) { fields.identifiers = JSON.stringify(fields.identifiers); }
}
const conf = typeof fields.confidence === 'number' ? fields.confidence : 0;
const needsReview = conf < 0.7;
const iso = (d) => { if (!d) return null; const s = String(d).slice(0,10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null; };
const today = new Date().toISOString().slice(0,10);
const rt = (s) => ({ rich_text: [{ text: { content: String(s == null ? '' : s).slice(0,1900) } }] });
const docType = String(fields.document_type || 'Other');
const issue = iso(fields.issue_date);
const exp = iso(fields.expiry_date);
let verUrl = String(fields.verification_url || '').trim();
if (!/^https?:\/\//.test(verUrl)) verUrl = '';
if (!verUrl && /^https?:\/\//.test(qrTxt.trim())) verUrl = qrTxt.trim().split(/\s/)[0];
const props = {
  'Document Name': { title: [{ text: { content: String(meta.file_name || docType || 'مستند').slice(0,1900) } }] },
  'Company': rt(meta.company),
  'CR Number': rt(meta.cr_number),
  'Document Type': { select: { name: docType.slice(0,90) } },
  'Platform': rt(fields.platform),
  'Authority': rt(fields.authority),
  'Identifiers': rt(fields.identifiers),
  'Status': rt(fields.status),
  'Extracted Fields JSON': rt(JSON.stringify(fields)),
  'Confidence': { number: conf },
  'Needs Human Review': { checkbox: needsReview },
  'Uploaded Date': { date: { start: today } },
  'Intake Page': rt(meta.intake_page_id),
  'Drive File ID': rt(meta.drive_file_id),
};
if (meta.drive_file_id) props['File URL'] = { url: 'https://drive.google.com/file/d/' + meta.drive_file_id + '/view' };
if (qrTxt) props['QR Data'] = rt(qrTxt);
if (verUrl) props['Verification URL'] = { url: verUrl.slice(0, 1900) };
if (issue) props['Issue Date'] = { date: { start: issue } };
if (exp) props['Expiry Date'] = { date: { start: exp } };
const out = [{ json: { document_type: docType, platform: fields.platform || '', expiry_date: exp, issue_date: issue, status: fields.status || '', identifiers: fields.identifiers || '', confidence: conf, needs_human_review: needsReview, company: meta.company || '', cr_number: meta.cr_number || '', qr_data: qrTxt, verification_url: verUrl, extracted: fields, notionPayload: { parent: { database_id: dbId }, properties: props }, dbConfigured: true, method: 'POST', url: 'https://api.notion.com/v1/pages' } }];
const PLATFORM_AR = { 'CR': 'السجل التجاري', 'Saudi Business Center': 'المركز السعودي للأعمال', 'Qiwa': 'قوى', 'Muqeem': 'مقيم', 'GOSI': 'GOSI', 'Mudad': 'مدد', 'ZATCA/VAT': 'الزكاة والضريبة (ZATCA)', 'Zakat': 'الزكاة والضريبة (ZATCA)', 'Chamber': 'الغرفة التجارية', 'National Address': 'العنوان الوطني', 'Balady': 'بلدي', 'Civil Defense': 'الدفاع المدني (سلامة)', 'Ejar': 'إيجار', 'MISA': 'MISA' };
const ACTION_AR = { 'Muqeem': 'تجديد إقامة', 'Qiwa': 'تجديد رخصة عمل', 'GOSI': 'تحديث اشتراك GOSI', 'Mudad': 'معالجة حماية الأجور' };
if (exp) {
  const regProps = {
    'المنشأة': { title: [{ text: { content: String(meta.company || 'منشأة').slice(0,1900) } }] },
    'السجل التجاري': rt(meta.cr_number),
    'الموظف أو الموضوع': rt((docType === 'Other' ? '' : (docType + ' — ')) + (meta.file_name || '')),
    'نوع الإجراء': { select: { name: ACTION_AR[docType] || 'تجديد شهادة/رخصة' } },
    'تاريخ الانتهاء': { date: { start: exp } },
    'آخر فحص': { date: { start: today } },
    'حالة الاشتراك': { select: { name: 'نشط' } },
    'ملاحظات': rt('أُنشئ آلياً من تحليل مستند مرفوع. ' + (fields.status || '') + (verUrl ? (' رابط التحقق: ' + verUrl) : '')),
  };
  const plat = PLATFORM_AR[docType]; if (plat) regProps['المنصة'] = { select: { name: plat } };
  out.push({ json: { method: 'POST', url: 'https://api.notion.com/v1/pages', notionPayload: { parent: { database_id: REGISTER_DB }, properties: regProps } } });
}
const pageId = meta.intake_page_id || '';
if (pageId) {
  const summary = ('تم تحليل مستند: ' + (docType || 'غير محدد') + (fields.status ? (' — ' + fields.status) : '') + '. الثقة: ' + Math.round(conf * 100) + '%' + (qrTxt ? ' — باركود التحقق مقروء ✓' : '') + (needsReview ? ' — يحتاج مراجعة بشرية.' : '.')).slice(0, 1900);
  const patchProps = { 'الحالة': { select: { name: needsReview ? 'مراجعة يدوية' : 'تمت المعالجة آلياً' } }, 'ملخص الوكيل': { rich_text: [{ text: { content: summary } }] }, 'آخر تحليل': { date: { start: today } } };
  const rc = Number(fields.row_count);
  if (docType === 'GOSI' && rc > 0) patchProps['عدد الموظفين'] = { number: rc };
  out.push({ json: { method: 'PATCH', url: 'https://api.notion.com/v1/pages/' + pageId, notionPayload: { properties: patchProps } } });
}
return out;

const s = $('تنظيم واستخراج JSON').first().json;
const saved = $input.first().json || {};
return [{ json: {
  status: 'ok',
  document_type: s.document_type, platform: s.platform,
  expiry_date: s.expiry_date, status_text: s.status,
  confidence: s.confidence, needs_human_review: s.needs_human_review,
  saved_to_notion: !!(saved && saved.id), notion_page_id: saved.id || null,
  db_configured: s.dbConfigured, extracted: s.extracted,
} }];

const meta = $('مدخلات الملف').first().json || {};
const rows = $input.all().map(i => i.json);
const rowCount = rows.length;
const headers = rowCount ? Object.keys(rows[0]) : [];
const fname = (meta.file_name || '').toLowerCase();
let docType = 'Other';
if (fname.indexOf('gosi') !== -1 || fname.indexOf('تأمين') !== -1 || fname.indexOf('تامين') !== -1) docType = 'GOSI';
if (fname.indexOf('muqeem') !== -1 || fname.indexOf('مقيم') !== -1) docType = 'Muqeem';
if (fname.indexOf('insurance') !== -1 || fname.indexOf('بوليصة') !== -1 || fname.indexOf('بوليصه') !== -1) docType = 'Insurance Policy';
const fields = {
  document_type: docType,
  platform: docType,
  authority: '',
  identifiers: 'عدد الصفوف: ' + rowCount + (headers.length ? (' — الأعمدة: ' + headers.slice(0,8).join('، ')) : ''),
  issue_date: null,
  expiry_date: null,
  status: rowCount > 0 ? ('تم استيراد ' + rowCount + ' سجل من ملف بيانات (Excel/CSV).') : 'تعذّرت قراءة بيانات الجدول — يحتاج مراجعة يدوية.',
  warnings: rowCount === 0 ? 'الملف فارغ أو غير مقروء' : '',
  row_count: rowCount,
  confidence: rowCount > 0 ? 0.75 : 0.15,
};
return [{ json: { content: JSON.stringify(fields) } }];

const meta = $('مدخلات الملف').first().json || {};
let mime = '';
try { mime = (($('تحميل الملف').first().binary || {}).data || {}).mimeType || ''; } catch (e) { mime = ''; }
mime = String(mime || '').toLowerCase().split(';')[0].trim();
let b64 = '';
try { b64 = ($('تحويل إلى Base64').first().json || {}).fileBase64 || ''; } catch (e) { b64 = ''; }
let qrData = '';
try {
  const q = $('فك الباركود').first().json || {};
  const sym = (q.symbol && q.symbol[0]) || {};
  if (sym.data && !sym.error) qrData = String(sym.data);
} catch (e) { qrData = ''; }
const prompt = 'أنت مستخرِج مستندات امتثال سعودية. اقرأ هذا المستند وأعِد JSON فقط (بدون أي نص آخر) بالمفاتيح: document_type (واحدة من: CR, Saudi Business Center, Qiwa, Muqeem, GOSI, Mudad, ZATCA/VAT, Zakat, Chamber, National Address, Balady, Civil Defense, Ejar, MISA, Insurance Policy, Other), platform, authority, identifiers (أي أرقام: السجل/الموحّد/المنشأة/الشهادة/الإقامة), issue_date (YYYY-MM-DD أو null), expiry_date (YYYY-MM-DD أو null), status, warnings, verification_url (رابط التحقق الإلكتروني من الباركود إن وجد أو null), confidence (0-1). حوّل التواريخ الهجرية إلى ميلادية إن أمكن. أعد JSON صالحاً فقط.'
  + (qrData ? ('\n\nمهم جداً: تم فك باركود (QR) الشهادة إلكترونياً ومحتواه:\n' + qrData.slice(0, 1500) + '\nاعتمد بيانات الباركود كمصدر موثوق للأرقام والتواريخ وصحة الشهادة، وإن كان رابطاً ضعه في verification_url.') : '');
const content = [];
if (b64 && mime.indexOf('image/') === 0) content.push({ type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } });
else if (b64 && mime === 'application/pdf') content.push({ type: 'file', file: { filename: (meta.file_name || 'document.pdf'), file_data: 'data:application/pdf;base64,' + b64 } });
if (content.length) content.push({ type: 'text', text: prompt });
else content.push({ type: 'text', text: prompt + '\n\nتنبيه: تعذّرت قراءة محتوى الملف مباشرة (صيغة غير مدعومة: ' + (mime || 'غير معروفة') + '). اسم الملف: ' + (meta.file_name || '') + ' — استنتج ما تستطيع وضع confidence منخفضاً (0.2 أو أقل).' });
return [{ json: { qrData: qrData, aiBody: { model: 'gpt-4o', max_tokens: 1500, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: content }] } } }];
